   Sign-off criterion: Idempotent re-load
   Method: (a) duplicate-version query per satellite; (b) re-run an already-loaded
       window and compare row counts
   Pass criteria / tolerance: No duplicate rows on re-run
   Owner: LUMIQ
   Vault location: BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL
   Maximus Travel RAW: RAW.MAXIMUS_TRAVEL
   Opus Travel RAW (prod): BAGIC_PROD_MIRROR_DB.OPUS_GG_DWHSTAGE
   Opus Travel RAW (test): BAGIC_PREPROD_CURATED_DB.UTILS
   Scope: Every standard + augmented satellite of the project; rows scoped by the
       project's TRAVEL RECORD_SOURCE value set (shared vault with partner).
   Snapshot schema (b): BAGIC_PREPROD_CURATED_DB.UTILS -- tables DM_H_CDC_SNAPSHOT /
       DM_H_RELOAD_SNAPSHOT (transient).
   Member plan: No DM-H member plan for travel yet; this file covers every satellite in
       the project. Trim once a plan is agreed (see partner DM-H_MEMBER_PLAN.md for the
       shape).
   Project in this file: MAXIMUS

