-- 1. MAXIMUS — SAT_ASSESSMENT_HEADER   [Implemented]
-- Grain (ASSESSMENT_HKEY, RECORD_SOURCE, LOAD_DATETIME). duplicate_row_groups = the same
-- version stored twice (what a non-idempotent re-run produces).
-- same_ldts_different_payload_info = two different payloads at one LOAD_DATETIME (a
-- source grain conflict, not a re-load duplicate) -- informational. standard satellite,
-- automate_dv.sat; PK ASSESSMENT_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS [4 col(s)].
----------------------------------------------------------------------------------------
with d as (
    select ASSESSMENT_HKEY, RECORD_SOURCE, LOAD_DATETIME, count(*) as n, count(distinct HASHDIFF) as hashdiffs
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS')
     group by ASSESSMENT_HKEY, RECORD_SOURCE, LOAD_DATETIME
    having count(*) > 1
)
select 'MAXIMUS' as project, 'SAT_ASSESSMENT_HEADER' as satellite,
       count_if(hashdiffs = 1)            as duplicate_row_groups,
       coalesce(sum(iff(hashdiffs = 1, n - 1, 0)), 0) as surplus_rows,
       count_if(hashdiffs > 1)            as same_ldts_different_payload_info,
       array_slice(array_agg(iff(hashdiffs = 1, to_varchar(ASSESSMENT_HKEY, 'HEX'), null)) within group (order by ASSESSMENT_HKEY), 0, 3) as examples,
       iff(duplicate_row_groups = 0, 'PASS', 'FAIL') as status
  from d;



