-- Grain (PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME). duplicate_row_groups = the same
-- version stored twice (what a non-idempotent re-run produces).
-- same_ldts_different_payload_info = two different payloads at one LOAD_DATETIME (a
-- source grain conflict, not a re-load duplicate) -- informational. standard satellite,
-- automate_dv.sat; PK PARTY_HKEY; 4 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS [3
-- col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [14 col(s)], MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS [3
-- col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [18 col(s)].
----------------------------------------------------------------------------------------
with d as (
    select PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME, count(*) as n, count(distinct HASHDIFF) as hashdiffs
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW')
     group by PARTY_HKEY, RECORD_SOURCE, LOAD_DATETIME
    having count(*) > 1
)
select 'MAXIMUS' as project, 'SAT_PARTY_ORGANISATION_PROFILE' as satellite,
       count_if(hashdiffs = 1)            as duplicate_row_groups,
       coalesce(sum(iff(hashdiffs = 1, n - 1, 0)), 0) as surplus_rows,
       count_if(hashdiffs > 1)            as same_ldts_different_payload_info,
       array_slice(array_agg(iff(hashdiffs = 1, to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as examples,
       iff(duplicate_row_groups = 0, 'PASS', 'FAIL') as status
  from d;



