----------------------------------------------------------------------------------------
-- 210. MAXIMUS — Re-load test: capture row counts   [Procedure]
-- Re-runs a window that is already loaded: the from_date / to_date vars pin
-- sat_multi_source / stitch_incremental to the same rows, so an idempotent load inserts
-- nothing. Run the DM-H1 set-up section first (creates the snapshot table).
----------------------------------------------------------------------------------------
-- Step 1: fix a load window that has ALREADY been loaded, e.g. yesterday
--   from_date = '<YYYY-MM-DD HH:MI:SS>'   to_date = '<YYYY-MM-DD HH:MI:SS>'
-- PARALLEL RUNS: replace <M#> with your member tag (M1 / M2 / M3) so the three testers
-- get distinct run_ids in the shared UTILS.DM_H_RELOAD_SNAPSHOT.
set DM_H_RUN = 'RELOAD_MAXIMUS_<M#>_' || to_char(current_timestamp(), 'YYYYMMDD_HH24MI');
set DM_H_PHASE = 'BEFORE';

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_RELOAD_SNAPSHOT (run_id, phase, project, satellite, row_count, captured_at)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', satellite, row_count, current_timestamp()
  from (
    select 'SAT_ASSESSMENT_HEADER' as satellite, count(*) as row_count from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS')
    union all select 'SAT_CHANNEL_DEFINITION' as satellite, count(*) as row_count from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION where RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW')
